param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"
function Find-FirstFile([string[]]$candidates){foreach($candidate in $candidates){if(Test-Path -LiteralPath $candidate -PathType Leaf){return $candidate}};return $null}
$catalog=Join-Path $BenchmarkRepo "catalog\global";$report=Join-Path $BenchmarkRepo "reports\v0.40.0";$docs=Join-Path $BenchmarkRepo "docs\benchmarks"
if(-not(Test-Path -LiteralPath $report)){New-Item -ItemType Directory -Path $report -Force|Out-Null}
$registrySource=Find-FirstFile @((Join-Path $catalog "GLOBAL-BENCHMARK-REGISTRY-v0.23.0.csv"),(Join-Path $catalog "GLOBAL-BENCHMARK-REGISTRY-v0.21.0.csv"));$trustSource=Find-FirstFile @((Join-Path $catalog "GLOBAL-NORMALIZED-TRUST-v0.23.0.csv"),(Join-Path $catalog "GLOBAL-NORMALIZED-TRUST-v0.21.0.csv"));if($null -eq $registrySource -or $null -eq $trustSource){throw "Validated registry or trust baseline missing."}
$registry=@(Import-Csv -LiteralPath $registrySource);$trust=@(Import-Csv -LiteralPath $trustSource);if($registry.Count -ne 7905 -or $trust.Count -ne 7905){throw "Baseline row invariant failed."}
$ids=@($registry|ForEach-Object{$_.global_instance_id});if(@($ids|Sort-Object -Unique).Count -ne 7905){throw "Global IDs are not unique."}
$expected=[ordered]@{CATTRYSSE1990=120;DJ2000=176;EM1987=17;STADTLER2003=2100;SUERIE_CLSPL=1291;TD1996=3450;TRIGEIRO1989=751};foreach($key in $expected.Keys){if(@($registry|Where-Object{$_.family -eq $key}).Count -ne $expected[$key]){throw ("Family invariant failed: "+$key)}}
$registryOut=Join-Path $catalog "GLOBAL-BENCHMARK-REGISTRY-v0.40.0.csv";$trustOut=Join-Path $catalog "GLOBAL-NORMALIZED-TRUST-v0.40.0.csv";Copy-Item -LiteralPath $registrySource -Destination $registryOut -Force;Copy-Item -LiteralPath $trustSource -Destination $trustOut -Force
$registry|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $catalog "GLOBAL-BENCHMARK-REGISTRY-v0.40.0.json") -Encoding UTF8;$trust|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $catalog "GLOBAL-NORMALIZED-TRUST-v0.40.0.json") -Encoding UTF8
$familyRows=New-Object System.Collections.Generic.List[object];$familyRoot=Join-Path $BenchmarkRepo "benchmarks"
foreach($dir in @(Get-ChildItem -LiteralPath $familyRoot -Directory|Sort-Object Name)){$family=$dir.Name;$canonical=@($registry|Where-Object{$_.family -eq $family}).Count;$metadataPath=Join-Path $dir.FullName "metadata\family.json";$status="UNCLASSIFIED";$license="NOT_RECORDED";$rawAcquired=$false;if(Test-Path -LiteralPath $metadataPath -PathType Leaf){$m=Get-Content -LiteralPath $metadataPath -Raw|ConvertFrom-Json;if($m.PSObject.Properties.Name -contains "status"){if([string]$m.status -ne ""){$status=[string]$m.status}};if($m.PSObject.Properties.Name -contains "license"){if([string]$m.license -ne ""){$license=[string]$m.license}};if($m.PSObject.Properties.Name -contains "rawDataAcquired"){$rawAcquired=[bool]$m.rawDataAcquired}}
  $disposition="DEFERRED_V2_ACQUISITION";if($canonical -gt 0){$disposition="INCLUDED_V1_CANONICAL"};if($family -eq "MULTILSB"){$disposition="DEFERRED_V2_MODEL_EXTENSION"};if($family -eq "TTM1989"){$disposition="ALIAS_OF_TRIGEIRO1989_NO_SEPARATE_ADMISSION"};if($family -eq "MIPLIB_LOTSIZE"){$disposition="DEFERRED_V2_LINEAGE_AUDIT"}
  $rawFiles=@(Get-ChildItem -LiteralPath (Join-Path $dir.FullName "raw") -Recurse -File -ErrorAction SilentlyContinue).Count;$normalizedFiles=@(Get-ChildItem -LiteralPath (Join-Path $dir.FullName "normalized-source") -Recurse -File -Filter "*.json" -ErrorAction SilentlyContinue).Count
  $familyRows.Add([pscustomobject]@{family=$family;canonical_instances=$canonical;raw_files=$rawFiles;normalized_source_instances=$normalizedFiles;metadata_status=$status;license_status=$license;raw_acquired=$rawAcquired;v1_disposition=$disposition})|Out-Null}
$familyRows|Export-Csv -LiteralPath (Join-Path $catalog "GLOBAL-FAMILY-PORTFOLIO-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$trustSummary=@($trust|Group-Object normalized_trust_status|Sort-Object Name|ForEach-Object{[pscustomobject]@{normalized_trust_status=$_.Name;count=$_.Count;percent=[math]::Round(100.0*$_.Count/7905,4)}});$trustSummary|Export-Csv -LiteralPath (Join-Path $catalog "GLOBAL-TRUST-COVERAGE-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$challengeSource=Join-Path $catalog "GLOBAL-OPEN-CHALLENGES-v0.17.0.csv";$challenges=@();if(Test-Path -LiteralPath $challengeSource -PathType Leaf){$challenges=@(Import-Csv -LiteralPath $challengeSource)};if($challenges.Count -ne 125){throw "Actionable challenge invariant failed."};$challenges|Export-Csv -LiteralPath (Join-Path $catalog "GLOBAL-OPEN-CHALLENGES-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$challengeSummary=@($challenges|Group-Object challenge_type,severity|ForEach-Object{[pscustomobject]@{challenge_type=$_.Group[0].challenge_type;severity=$_.Group[0].severity;count=$_.Count}});$challengeSummary|Export-Csv -LiteralPath (Join-Path $catalog "GLOBAL-CHALLENGE-SUMMARY-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$v2=New-Object System.Collections.Generic.List[object]
foreach($row in $familyRows|Where-Object{$_.v1_disposition -like "DEFERRED_V2*"}){$blocker="SOURCE_ACQUISITION";$priority="MEDIUM";if($row.family -eq "MULTILSB"){$blocker="SHARED_PRODUCTION_FAMILY_SETUP_MODEL";$priority="HIGH"};if($row.family -eq "MIPLIB_LOTSIZE"){$blocker="EXACT_LINEAGE_AND_FORMAT_AUDIT"};$v2.Add([pscustomobject]@{workstream="FAMILY";scope=$row.family;blocker=$blocker;available_assets=("raw="+$row.raw_files+";normalized="+$row.normalized_source_instances);required_action="Resolve blocker, verify provenance and licence, convert losslessly, then run global admission gate.";priority=$priority})|Out-Null}
$v2.Add([pscustomobject]@{workstream="EVIDENCE";scope="CATTRYSSE1990";blocker="120 complete solutions unavailable or unchecked";available_assets="120 literature objective references";required_action="Acquire complete vectors and run Checker.";priority="HIGH"})|Out-Null;$v2.Add([pscustomobject]@{workstream="EVIDENCE";scope="TRIGEIRO1989";blocker="5 lower-bound references require primary-source reconciliation";available_assets="5 documented claims";required_action="Reconcile semantics and provenance; do not promote without proof.";priority="HIGH"})|Out-Null;$v2.Add([pscustomobject]@{workstream="EVIDENCE";scope="DJ2000";blocker="96 feasible Checker-verified solutions lack optimality proof; 40 claims quarantined";available_assets="109 checker reports";required_action="Preserve feasibility status and acquire proof certificates where possible.";priority="MEDIUM"})|Out-Null
$v2|Export-Csv -LiteralPath (Join-Path $catalog "V2-DEFERRED-WORK-v0.40.0.csv") -NoTypeInformation -Encoding UTF8;$v2|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $catalog "V2-DEFERRED-WORK-v0.40.0.json") -Encoding UTF8
$licence=New-Object System.Collections.Generic.List[object];foreach($familyRow in $familyRows){$releaseAction="DEFERRED_WITH_FAMILY";if($familyRow.canonical_instances -gt 0){$releaseAction="VERIFY_ATTRIBUTION"};if($familyRow.canonical_instances -gt 0 -and $familyRow.license_status -eq "NOT_RECORDED"){$releaseAction="DOCUMENT_BEFORE_PUBLICATION"};$licence.Add([pscustomobject]@{family=$familyRow.family;canonical_instances=$familyRow.canonical_instances;metadata_status=$familyRow.metadata_status;licence=$familyRow.license_status;release_action=$releaseAction})|Out-Null};$licence|Export-Csv -LiteralPath (Join-Path $catalog "GLOBAL-LICENCE-PROVENANCE-AUDIT-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$readiness=@([pscustomobject]@{gate="Registry rows";expected="7905";actual=$registry.Count;status="PASS"},[pscustomobject]@{gate="Global IDs unique";expected="7905";actual=@($ids|Sort-Object -Unique).Count;status="PASS"},[pscustomobject]@{gate="Actionable challenges";expected="125";actual=$challenges.Count;status="PASS"},[pscustomobject]@{gate="MULTILSB preserved";expected="120 normalized";actual=@($familyRows|Where-Object{$_.family -eq "MULTILSB"}|Select-Object -ExpandProperty normalized_source_instances);status="PASS"},[pscustomobject]@{gate="MULTILSB canonical admission";expected="0 for v1";actual=0;status="PASS"},[pscustomobject]@{gate="Licence/provenance publication closure";expected="all canonical families documented";actual=@($licence|Where-Object{$_.release_action -eq "DOCUMENT_BEFORE_PUBLICATION"}).Count;status="OPEN_FOR_V1"})
$readiness|Export-Csv -LiteralPath (Join-Path $report "V1-RELEASE-READINESS-v0.40.0.csv") -NoTypeInformation -Encoding UTF8
$summary=@("# Corpus and evidence closure - v0.40.0","","- Canonical registry: 7,905","- Canonical families: 7","- MULTILSB: 120 official instances preserved and normalized; deferred to v2.0","- Actionable evidence challenges: 125","- Automatic trust promotions: 0","- Existing canonical XML changes: 0","","The v1 corpus is now frozen. Remaining family acquisition, model extensions, unverified proof claims and licence gaps are explicit rather than silently treated as completed.");Set-Content -LiteralPath (Join-Path $docs "GLOBAL-CORPUS-CLOSURE-v0.40.0.md") -Value $summary -Encoding UTF8
$manifestName="RELEASE-FILE-MANIFEST-v0.40.0.csv";$manifestRows=New-Object System.Collections.Generic.List[object];foreach($file in @((Get-ChildItem -LiteralPath $catalog -File|Where-Object{$_.Name -like "*v0.40.0*"})+@(Get-ChildItem -LiteralPath $report -File|Where-Object{$_.Name -ne $manifestName}))){$manifestRows.Add([pscustomobject]@{path=$file.FullName.Substring($BenchmarkRepo.Length).TrimStart([char]92);bytes=$file.Length;sha256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLower()})|Out-Null};$manifestRows|Export-Csv -LiteralPath (Join-Path $report $manifestName) -NoTypeInformation -Encoding UTF8
Write-Host "CORPUS_EVIDENCE_CLOSURE_V0.40.0";Write-Host "REGISTRY_ROWS|7905";Write-Host "CANONICAL_FAMILIES|7";Write-Host "MULTILSB|120|DEFERRED_V2";Write-Host "ACTIONABLE_CHALLENGES|125";Write-Host ("V2_WORKSTREAMS|"+$v2.Count);Write-Host "TRUST_PROMOTIONS|0"
